import { Entity } from '../../Engine/Entity';
import type { WeaponData } from './WeaponData';

export type MovePattern = 'none' | 'straight' | 'sine' | 'arc' | 'dive' | 'sprint';

export type PlaneKind = 'player' | 'enemy' | 'boss' | 'turret';  

export class Plane extends Entity {
    readonly kind: PlaneKind;

    public hp = 100;
    public maxHp = 100;
    public weapons: WeaponData[] = [];  ;
    public movePattern: MovePattern = 'none';

    public invincibleTimer = 0;
    public hitInvincibleDuration = 0;

    //============player================
     /** 当前经验值。仅玩家使用 */
    public exp = 0;
    /** 当前等级。1 = 初始等级。仅玩家使用 */
    public level = 1;
    /** 升到下一级所需经验。仅玩家使用 */
    public expToNext = 50;
    public cardStacks: Map<string, number> = new Map();

    
    //================enemy========================
    /** 直线移动方向。-1/0/1。仅 'straight' 模式用 */
    public moveDirX: -1 | 0 | 1 = 0;
    public moveDirY: -1 | 0 | 1 = 0;

    /** 移动速度（像素/秒） */
    public moveSpeed = 100;
    
   /** 函数型移动的基准点 X。sine/arc/半圆/自定义函数都以此为原点 */
    public originX = 0;

    /** 函数型移动的基准点 Y。sine/arc/半圆/自定义函数都以此为原点 */
    public originY = 0;

    /** 正弦移动的相位累积值（运行时状态）。其他模式不用 */
    public movePhase = 0;
    /** 移动频率（弧度/秒） */
    public moveFrequency = 3;
    /** 移动振幅（像素） */
    public moveAmplitude = 80;

    /** 碰撞检测半径（像素）。用于 CombatSystem 的圆形碰撞判定 */
    public collisionRadius = 20;

    constructor(kind: PlaneKind) {
        super();
        this.kind = kind;
    }
}